create extension if not exists pgcrypto;
create type device_status as enum ('online','offline');
create table users(id uuid primary key default gen_random_uuid(),email text unique not null,password_hash text not null,email_verified_at timestamptz,role text not null default 'user' check(role in ('user','admin')),created_at timestamptz not null default now(),deleted_at timestamptz);
create table devices(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id) on delete cascade,name text not null,model text not null,phone text,imei1_encrypted bytea,imei2_encrypted bytea,pairing_token_hash text not null,status device_status not null default 'offline',battery smallint check(battery between 0 and 100),last_seen timestamptz,lost_mode boolean not null default false,lost_message text,revoked_at timestamptz,deleted_at timestamptz,created_at timestamptz not null default now());
create index devices_owner_idx on devices(user_id) where deleted_at is null;
create table location_reports(id bigint generated always as identity primary key,device_id uuid not null references devices(id) on delete cascade,latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),accuracy real not null,battery smallint,network text,online boolean not null default true,recorded_at timestamptz not null,received_at timestamptz not null default now());
create index location_device_time_idx on location_reports(device_id,recorded_at desc);
create table geofences(id uuid primary key default gen_random_uuid(),device_id uuid not null references devices(id) on delete cascade,name text not null,latitude double precision not null,longitude double precision not null,radius_m integer not null check(radius_m between 25 and 100000),trigger text not null check(trigger in ('enter','exit','both')),created_at timestamptz not null default now());
create table events(id bigint generated always as identity primary key,device_id uuid references devices(id) on delete cascade,type text not null,payload jsonb not null default '{}',created_at timestamptz not null default now(),read_at timestamptz);
create table audit_logs(id bigint generated always as identity primary key,user_id uuid references users(id) on delete set null,action text not null,target_id text,ip inet,metadata jsonb not null default '{}',created_at timestamptz not null default now());
revoke all on location_reports,devices from public;
